import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Lingma tutorial","description":"Install TONGYI Lingma / Qoder CN as a standalone IDE or IDE plugin, sign in with an Alibaba Cloud account, then use completion and the three chat modes.","frontmatter":{"title":"Lingma tutorial","description":"Install TONGYI Lingma / Qoder CN as a standalone IDE or IDE plugin, sign in with an Alibaba Cloud account, then use completion and the three chat modes.","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"products/lingma/lingma.md","filePath":"products/lingma/lingma.md","lastUpdated":1787110548000}'),i={name:"products/lingma/lingma.md"};function l(r,e,s,d,h,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="lingma-tutorial" tabindex="-1">Lingma tutorial <a class="header-anchor" href="#lingma-tutorial" aria-label="Permalink to &quot;Lingma tutorial&quot;">​</a></h1><blockquote><p>This is a <strong>tutorial</strong>. Do it in order: pick a surface → copy the official install text → sign in → complete → three chat modes.</p><p>Names: <a href="./lingma-glossary.html">glossary</a>. Keys and plans: <a href="./lingma-cheatsheet.html">cheatsheet</a>. Recipes: <a href="./lingma-cookbook.html">cookbook</a>.</p></blockquote><p>Goal: go from &quot;the Chinese Copilot&quot; to &quot;it completes, answers, and edits in my IDE&quot;.</p><h2 id="step-0-name-what-you-are-installing" tabindex="-1">Step 0: Name what you are installing <a class="header-anchor" href="#step-0-name-what-you-are-installing" aria-label="Permalink to &quot;Step 0: Name what you are installing&quot;">​</a></h2><p>The Help Center calls the coding sub-product <strong>Qoder CN</strong> (formerly TONGYI Lingma) and offers two ways to use it (<a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">Installation guide</a>):</p><blockquote><p>Qoder CN 为您提供两种使用方式。您可以选择下载开箱即用的 Qoder CN IDE，也可以选择在您现有的开发工具中直接安装 Qoder CN 插件。安装后登录账号即可开始使用。</p></blockquote><p>EN Help Center equivalent: install Qoder CN IDE, or install the plugin in an existing IDE, then sign in (<a href="https://www.alibabacloud.com/help/en/lingma/installation-and-login-guide/" target="_blank" rel="noreferrer">Setup and install</a>).</p><table tabindex="0"><thead><tr><th>You already have</th><th>Install</th><th>Official stance</th></tr></thead><tbody><tr><td>No preference / want an AI-native IDE</td><td><strong>Qoder CN IDE</strong> (marketing still says Lingma IDE)</td><td>Current default</td></tr><tr><td>IntelliJ IDEA / WebStorm / PyCharm</td><td><strong>JetBrains plugin</strong></td><td>Current iteration surface</td></tr><tr><td>VS Code</td><td><strong>VS Code plugin</strong></td><td>Still installable; official text says updates slowed / discontinued</td></tr><tr><td>Visual Studio 2022 / 2019</td><td><strong>Visual Studio plugin</strong></td><td>Chat is Ask-only for now</td></tr></tbody></table><p>Individual edition prerequisite: an Alibaba Cloud account; sign in with the primary account (<a href="https://help.aliyun.com/zh/lingma/individual-edition-quick-start" target="_blank" rel="noreferrer">Individual quick start</a>, <a href="https://www.alibabacloud.com/help/en/lingma/getting-started/individual-edition-quick-start" target="_blank" rel="noreferrer">EN</a>).</p><h2 id="step-1-install" tabindex="-1">Step 1: Install <a class="header-anchor" href="#step-1-install" aria-label="Permalink to &quot;Step 1: Install&quot;">​</a></h2><p>The steps below are <strong>copied from official pages</strong>. Do not merge the old and new search strings. Use the wording on the page you opened.</p><h3 id="_1-1-standalone-ide" tabindex="-1">1.1 Standalone IDE <a class="header-anchor" href="#_1-1-standalone-ide" aria-label="Permalink to &quot;1.1 Standalone IDE&quot;">​</a></h3><p>Marketing site <a href="https://lingma.aliyun.com/download" target="_blank" rel="noreferrer">lingma.aliyun.com/download</a>:</p><blockquote><p>Lingma IDE 将增强上下文工程与智能体无缝集成，全面理解代码库，轻松处理复杂任务，同时兼容 JetBrains IDEs 等主流编程工具，开发者可以自由选择。</p><p>全面集成智能编码助手的能力，开箱即用更简单，无需安装插件即可享受高效、智能的编程体验。</p></blockquote><p>OS lines on that page:</p><ul><li><strong>macOS</strong> 11.0+</li><li><strong>Windows</strong> 10/11</li><li><strong>Linux</strong> <code>.deb</code> / <code>.rpm</code></li></ul><p>The Help Center names the same client <strong>Qoder CN IDE</strong>, points downloads at <a href="https://qoder.com.cn/download" target="_blank" rel="noreferrer">https://qoder.com.cn/download</a>, and writes:</p><blockquote><p>适用操作系统：Windows 10/11（x64）、macOS 11.0 、Linux x64 (.deb/.rpm) 或更新版本。</p></blockquote><p>Both URLs are official. New-brand downloads go through <code>qoder.com.cn/download</code>. Official upgrade path: uninstall the original Lingma IDE, then install Qoder CN IDE (<a href="https://help.aliyun.com/zh/lingma/billing-description" target="_blank" rel="noreferrer">Billing</a>).</p><h3 id="_1-2-jetbrains-plugin" tabindex="-1">1.2 JetBrains plugin <a class="header-anchor" href="#_1-2-jetbrains-plugin" aria-label="Permalink to &quot;1.2 JetBrains plugin&quot;">​</a></h3><p>Marketing download page, IntelliJ IDEA example:</p><blockquote><p><strong>方式一：从插件市场安装</strong></p><p>点击导航-插件，打开应用市场，搜索通义灵码（TONGYI Lingma），找到通义灵码后点击安装。</p><p><strong>方式二：下载离线包安装</strong></p><ol><li>下载 JetBrains IDEs 的 zip 安装包；</li><li>点击导航-插件，点击设置图标，下拉菜单中单击从本地安装插件，选择下载的 zip 文件后安装。</li></ol><p>重启 IntelliJ IDEA，重启成功后登录阿里云账号，即刻开启智能编码之旅。</p></blockquote><p>Help Center (new display name):</p><blockquote><p>打开 IntelliJ IDEA 设置窗口，在插件市场中搜索 Qoder CN，找到 Qoder CN 后单击安装。</p><p>安装完成后，请重启 IntelliJ IDEA。</p></blockquote><p>Offline zip from Help Center: <a href="https://tongyi-code.oss-cn-hangzhou.aliyuncs.com/jetbrain/tongyi-jetbrains-latest.zip" target="_blank" rel="noreferrer">tongyi-jetbrains-latest.zip</a>. New-brand zip: <a href="https://qodercn-jb.oss-cn-hangzhou.aliyuncs.com/qodercn-jetbrains-latest.zip" target="_blank" rel="noreferrer">qodercn-jetbrains-latest.zip</a>.</p><p>Compatibility: JetBrains IDEs <strong>2020.3+</strong>. Full matrix: <a href="./lingma-cheatsheet.html#compatible-ides-and-os">Cheatsheet</a>.</p><h3 id="_1-3-visual-studio-code-plugin" tabindex="-1">1.3 Visual Studio Code plugin <a class="header-anchor" href="#_1-3-visual-studio-code-plugin" aria-label="Permalink to &quot;1.3 Visual Studio Code plugin&quot;">​</a></h3><p>Read the official stance first:</p><blockquote><p>产品功能迭代将主要集中在 Qoder CN IDE 和 Qoder CN JetBrains 插件中，VSCode 插件更新节奏将会放缓。如果您在使用 VSCode 插件过程中遇到问题或不便，建议切换到 Qoder CN IDE. (<a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">Installation guide</a>)</p></blockquote><p>EN update log: &quot;VS Code plugin support discontinued … no longer part of the product suite.&quot; (<a href="https://www.alibabacloud.com/help/en/lingma/product-overview/qoder-cn-update-log" target="_blank" rel="noreferrer">Update log</a>)</p><p>Help Center install text:</p><blockquote><p>下载并安装 Visual Studio Code <strong>1.68.0 及以上版本</strong>。</p><p><strong>方法 1：从插件市场安装</strong></p><p>单击 <a href="vscode:extension/Alibaba-Cloud.tongyi-lingma" target="_blank" rel="noreferrer">立即安装</a> ，唤起 Visual Studio Code 插件市场直接安装，安装后请重启 IDE，即可开启智能编码之旅。</p><p>打开 Visual Studio Code 扩展窗口，搜索 Qoder CN，找到 Qoder CN 后单击安装。</p><p><strong>方法 2：下载安装包安装</strong></p><p>单击下方链接，下载 Visual Studio Code 的 VSIX 安装包：<a href="https://tongyi-code.oss-cn-hangzhou.aliyuncs.com/vscode/tongyi-lingma-latest.vsix" target="_blank" rel="noreferrer">Qoder CN-VS Code</a></p><p>打开 Visual Studio Code 后，单击扩展，单击更多按钮，在下拉菜单中单击 <strong>从 VSIX 安装</strong> ，选择下载的 VSIX 文件后安装。</p><p>安装完成后，请重启 Visual Studio Code。</p></blockquote><p>Marketplace ID remains <code>Alibaba-Cloud.tongyi-lingma</code>. Display name: <strong>Qoder CN (Formerly Lingma)</strong>.</p><p>If the sidebar icon is missing:</p><blockquote><p>如果安装后在侧边导航上找不到 Qoder CN 入口，可鼠标聚焦在侧边导航后右键查看，勾选 Qoder CN 后即可将插件入口配置在侧边导航上。</p></blockquote><h3 id="_1-4-visual-studio" tabindex="-1">1.4 Visual Studio <a class="header-anchor" href="#_1-4-visual-studio" aria-label="Permalink to &quot;1.4 Visual Studio&quot;">​</a></h3><p>Help Center does not publish a click-by-click Visual Studio walkthrough. It only says: install from the marketplace or an install package (<a href="https://help.aliyun.com/zh/lingma/installation-and-login-guide/" target="_blank" rel="noreferrer">Setup and install</a>). Compatible versions: Visual Studio <strong>2022 17.3.0+</strong> or <strong>2019 16.3.0+</strong>, Windows 10+ (<a href="https://help.aliyun.com/zh/lingma/compatible-ide-and-system" target="_blank" rel="noreferrer">Compatible IDEs</a>). Chat on Visual Studio is <strong>Ask-only</strong> for now (<a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">Chat overview</a>). This page does not invent the missing clicks.</p><h2 id="step-2-sign-in" tabindex="-1">Step 2: Sign in <a class="header-anchor" href="#step-2-sign-in" aria-label="Permalink to &quot;Step 2: Sign in&quot;">​</a></h2><p>Individual edition (<a href="https://help.aliyun.com/zh/lingma/individual-edition-quick-start" target="_blank" rel="noreferrer">Individual quick start</a>):</p><blockquote><ol><li>安装完成后，选择 阿里云中国站账号登录 ，前往阿里云登录页完成登录。</li><li>在阿里云登录页面完成登录，后续即可看到登录成功页面。</li><li>回到 IDE 端即可开始使用 Qoder CN 。</li></ol><p>登录成功页面将展示账号名称和 Account ID 等信息。在 IDE 中，可通过 TONGYI Lingma 插件面板右上角的账号名称确认登录状态。</p></blockquote><p>EN Help Center: you can log on with an Alibaba Cloud account. Help Center also documents <strong>AK/SK</strong> login (common for remote SSH). Business / Dedicated login is a different path (<a href="https://help.aliyun.com/zh/lingma/installation-and-login-guide/" target="_blank" rel="noreferrer">Setup and install</a>); this tutorial does not cover the enterprise console.</p><h2 id="step-3-inline-completion" tabindex="-1">Step 3: Inline completion <a class="header-anchor" href="#step-3-inline-completion" aria-label="Permalink to &quot;Step 3: Inline completion&quot;">​</a></h2><p>Open a real frontend file and type. Official definition (<a href="https://help.aliyun.com/zh/lingma/what-is-qoder-cn" target="_blank" rel="noreferrer">What is Qoder CN</a>):</p><blockquote><p>根据当前语法和跨文件的代码上下文，自动感知当前工程，实时生成行、函数级代码。</p><p>通过注释描述您想要的功能，可直接在编辑器区生成代码。</p></blockquote><p>Marketplace English: &quot;generate line-level or function-level code … based on the context of your current or related files.&quot; Accept with <strong>Tab</strong> (<a href="https://help.aliyun.com/zh/lingma/plug-in-configuration-guide" target="_blank" rel="noreferrer">Plugin configuration</a>). Write the intent in a comment.</p><p>Next Edit Suggestion (NES) is a different feature. See <a href="./lingma-cookbook.html#turn-on-next-edit-suggestion-nes">Cookbook</a>.</p><h2 id="step-4-pick-a-chat-mode" tabindex="-1">Step 4: Pick a chat mode <a class="header-anchor" href="#step-4-pick-a-chat-mode" aria-label="Permalink to &quot;Step 4: Pick a chat mode&quot;">​</a></h2><p>Open chat (<a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">Chat overview</a>):</p><table tabindex="0"><thead><tr><th>Action</th><th>macOS</th><th>Windows</th></tr></thead><tbody><tr><td>Toggle chat</td><td><code>⌘ ⇧ L</code> (JetBrains, VS Code); <code>⌘ L</code> (Lingma IDE)</td><td><code>Ctrl Shift L</code></td></tr></tbody></table><p>Three official modes in one thread — you can switch without starting a new chat:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Official meaning</th><th>Use it when</th></tr></thead><tbody><tr><td><strong>Ask</strong></td><td>R&amp;D Q&amp;A; <strong>does not edit project files</strong></td><td>You need to understand first</td></tr><tr><td><strong>Edit</strong></td><td>Precise multi-file edits, reviewable</td><td>You know which files</td></tr><tr><td><strong>Agent</strong></td><td>Plans, uses tools (terminal, MCP), end-to-end</td><td>You give the goal</td></tr></tbody></table><p>Support matrix is official, not inferred:</p><ul><li><strong>Visual Studio Code:</strong> all three</li><li><strong>Lingma IDE / JetBrains plugin:</strong> Ask + Agent; <strong>no Edit</strong></li><li><strong>Visual Studio:</strong> Ask only for now</li><li>Latest chat features: upgrade VS Code / JetBrains plugins to <strong>2.5.0 or later</strong></li></ul><p>Official prompt advice (do not rewrite as &quot;usually&quot;):</p><blockquote><ul><li>Describe the task as a structured goal plus steps.</li><li>Attach context: files, images, codebase, codeChanges.</li><li>State language, style, format, and change targets.</li><li>Iterate.</li></ul></blockquote><p>Accept or reject file diffs before they merge into the original files.</p><h2 id="step-5-watch-terminal-confirms-in-agent-mode" tabindex="-1">Step 5: Watch terminal confirms in Agent mode <a class="header-anchor" href="#step-5-watch-terminal-confirms-in-agent-mode" aria-label="Permalink to &quot;Step 5: Watch terminal confirms in Agent mode&quot;">​</a></h2><p>Agent mode can edit many files and run the terminal. Official default (<a href="https://help.aliyun.com/zh/lingma/agent" target="_blank" rel="noreferrer">Agent</a>):</p><blockquote><p>默认每次执行命令前需要开发者进行确认：单击 <strong>运行</strong> 发送到 IDE Terminal；单击 <strong>取消</strong> 跳过此次命令。</p></blockquote><p>Do not enable the auto-run allowlist on day one. MCP calls also ask before they run. Recipes: <a href="./lingma-cookbook.html">Cookbook</a>.</p><h2 id="step-6-safety-habits" tabindex="-1">Step 6: Safety habits <a class="header-anchor" href="#step-6-safety-habits" aria-label="Permalink to &quot;Step 6: Safety habits&quot;">​</a></h2><ul><li><strong>Review generated code</strong>, especially auth, payments, and SQL.</li><li>In Agent mode, <strong>do not click Run</strong> on a command you cannot read.</li><li>Enterprise knowledge bases are enterprise features. Do not assume they exist on an individual account.</li><li>This site does not document model internals. See <a href="/tech/fundamentals/LLM.html">Learn LLM</a>.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>Wrong mode, weak prompts, MCP → <a href="./lingma-cookbook.html">Cookbook</a></li><li>URLs / shortcuts / plans → <a href="./lingma-cheatsheet.html">Cheatsheet</a></li><li>Rename and &quot;not this&quot; → <a href="./lingma-glossary.html">Glossary</a></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">Installation guide</a></li><li><a href="https://lingma.aliyun.com/download" target="_blank" rel="noreferrer">Marketing download page</a></li><li><a href="https://help.aliyun.com/zh/lingma/individual-edition-quick-start" target="_blank" rel="noreferrer">Individual quick start</a></li><li><a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">Chat overview</a></li><li><a href="https://help.aliyun.com/zh/lingma/what-is-qoder-cn" target="_blank" rel="noreferrer">What is Qoder CN</a></li><li><a href="https://www.alibabacloud.com/help/en/lingma/" target="_blank" rel="noreferrer">EN Help Center</a></li></ul>',66)])])}const b=t(i,[["render",l]]);export{f as __pageData,b as default};
